const BANGARAM_LOCATIONS=[{name:"Bangaram Island",lat:10.9526,lng:72.2708,description:"The largest island in the atoll, uninhabited apart from resort staff and visitors, ringed by a shallow coral lagoon."},{name:"Bangaram Lagoon",lat:10.955,lng:72.265,description:"A shallow, crystal-clear lagoon enclosed by coral reef, shared with the neighbouring islets of the atoll."},{name:"Thinnakara Island",lat:10.928,lng:72.245,description:"A tiny, teardrop-shaped islet just across the lagoon from Bangaram, sharing the same coralline bank."},{name:"Agatti Island (Gateway)",lat:10.8467,lng:72.1833,description:"Home to the nearest airport and jetty; visitors reach Bangaram from here by boat."},{name:"Parali Islets",lat:10.97,lng:72.29,description:"A string of small, uninhabited islets — Parali I, II and III — on the northern edge of the shared lagoon."}],BANGARAM_GALLERY=[{src:"../../assets/travel_islands.png",caption:"Bangaram Island's coral atoll from above"},{src:"../../assets/travel_beaches.png",caption:"White-sand beach fringed by coconut palms"},{src:"../../assets/travel_hidden.png",caption:"The secluded lagoon shared with Thinnakara"},{src:"../../assets/river1.png",caption:"Crystal-clear waters ideal for snorkelling"}],BANGARAM_FACTS=["Bangaram is uninhabited except for resort staff and visitors — there is no permanent civilian population on the island.","The island's shared lagoon spans roughly 125 square kilometres, ringed by a coral reef connecting Bangaram to Thinnakara, the Parali islets and Kalpitty.","A shallow submarine ridge links the Bangaram atoll's reef to the reef of neighbouring Agatti Island.","Lagoon visibility around Bangaram can reach 20 to 30 metres on a calm day, letting snorkellers see coral gardens straight from the shore.","At night, bioluminescent plankton sometimes washes ashore, giving the waterline a faint bluish glow.","Coral reefs here were affected by bleaching linked to the 1998 El Niño, and recovery has been gradual due to the atoll's shallow, sun-warmed waters.","The island's centre holds a long brackish pond fringed by screw pine and coconut palms, adding to Bangaram's quiet, undeveloped character."];let map,currentGalleryIndex=0,factIndex=0;function initTabs(){const e=document.querySelectorAll(".bangaram-tab-btn"),a=document.querySelectorAll(".bangaram-tab-panel");e.forEach(t=>{t.addEventListener("click",()=>{const n=t.getAttribute("data-tab");e.forEach(e=>e.classList.remove("active")),t.classList.add("active"),a.forEach(e=>{e.classList.toggle("active",e.id==="tab-"+n)})})})}function initGallery(){const e=document.getElementById("bangaram-gallery-grid");e&&(e.innerHTML="",BANGARAM_GALLERY.forEach((a,t)=>{const n=document.createElement("figure");n.className="bangaram-gallery-item",n.innerHTML=`\n      <img src="${a.src}" alt="${a.caption}" loading="lazy">\n      <figcaption>${a.caption}</figcaption>\n    `,n.addEventListener("click",()=>openLightbox(t)),e.appendChild(n)}))}function initLightbox(){document.querySelectorAll("[data-close-lightbox]").forEach(e=>{e.addEventListener("click",closeLightbox)});const e=document.getElementById("bangaram-lightbox-prev"),a=document.getElementById("bangaram-lightbox-next");e&&e.addEventListener("click",()=>showGalleryImage(currentGalleryIndex-1)),a&&a.addEventListener("click",()=>showGalleryImage(currentGalleryIndex+1)),document.addEventListener("keydown",e=>{const a=document.getElementById("bangaram-lightbox");a&&!a.hidden&&("Escape"===e.key&&closeLightbox(),"ArrowRight"===e.key&&showGalleryImage(currentGalleryIndex+1),"ArrowLeft"===e.key&&showGalleryImage(currentGalleryIndex-1))})}function openLightbox(e){const a=document.getElementById("bangaram-lightbox");a&&(a.hidden=!1,document.body.style.overflow="hidden",showGalleryImage(e))}function closeLightbox(){const e=document.getElementById("bangaram-lightbox");e&&(e.hidden=!0,document.body.style.overflow="")}function showGalleryImage(e){const a=BANGARAM_GALLERY.length;currentGalleryIndex=(e+a)%a;const t=BANGARAM_GALLERY[currentGalleryIndex],n=document.getElementById("bangaram-lightbox-image"),o=document.getElementById("bangaram-lightbox-caption");n&&(n.src=t.src),n&&(n.alt=t.caption),o&&(o.textContent=t.caption)}function initFactsRotator(){const e=document.getElementById("bangaram-fact-text"),a=document.getElementById("bangaram-fact-dots");function t(t){factIndex=t,e.style.opacity="0",setTimeout(()=>{e.textContent=BANGARAM_FACTS[factIndex],e.style.opacity="1"},200),a&&[...a.children].forEach((e,a)=>e.classList.toggle("active",a===factIndex))}e&&(a&&BANGARAM_FACTS.forEach((e,n)=>{const o=document.createElement("button");o.className="bangaram-fact-dot"+(0===n?" active":""),o.setAttribute("aria-label","Show fact "+(n+1)),o.addEventListener("click",()=>t(n)),a.appendChild(o)}),t(0),setInterval(()=>t((factIndex+1)%BANGARAM_FACTS.length),6e3))}function initMap(){document.getElementById("bangaram-map")&&"undefined"!=typeof L&&(map=L.map("bangaram-map",{scrollWheelZoom:!1,minZoom:8}).setView([10.93,72.24],11),L.tileLayer("https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png",{attribution:"&copy; OpenStreetMap contributors &copy; CARTO",maxZoom:18}).addTo(map),BANGARAM_LOCATIONS.forEach(e=>{L.circleMarker([e.lat,e.lng],{radius:8,color:"#ff9933",fillColor:"#ffb01f",fillOpacity:.85,weight:2}).addTo(map).bindPopup(`<strong>${e.name}</strong><br>${e.description}`)}))}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initGallery(),initFactsRotator(),initMap(),initLightbox()});